import{_ as o,o as t,c as r,aw as i}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"HTTP Status Codes","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/http/http/4-http-status-codes.md","filePath":"wiki/dev-commit/network/http/http/4-http-status-codes.md"}'),n={name:"wiki/dev-commit/network/http/http/4-http-status-codes.md"};function s(l,e,c,d,a,m){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="http-status-codes" tabindex="-1">HTTP Status Codes <a class="header-anchor" href="#http-status-codes" aria-label="Permalink to &quot;HTTP Status Codes&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Коды состояния HTTP</p><ul><li><strong>Коды состояния HTTP</strong> - код состояния является частью первой строки ответа сервера. Он представляет собой целое число из трёх цифр. Первая цифра указывает на класс состояния. За кодом ответа обычно следует отделённая пробелом поясняющая фраза на английском языке, которая разъясняет причину ответа</li></ul></div><h2 id="классы-кодов" tabindex="-1">Классы кодов <a class="header-anchor" href="#классы-кодов" aria-label="Permalink to &quot;Классы кодов&quot;">​</a></h2><ul><li><strong><code>1xx</code></strong> - Информационный (informational). Информирование о процессе передачи</li><li><strong><code>2xx</code></strong> - Успех (Success). Информирование о случаях успешного принятия и обработки запроса клиента</li><li><strong><code>3xx</code></strong> - Перенаправление (Redirection). Сообщает клиенту, что для успешного выполнения операции необходимо сделать другой запрос, как правило, по другому URI</li><li><strong><code>4xx</code></strong> - Ошибка клиента (Client Error)</li><li><strong><code>5xx</code></strong> - Ошибка сервера (Server Error)</li></ul><h2 id="список-кодов" tabindex="-1">Список кодов <a class="header-anchor" href="#список-кодов" aria-label="Permalink to &quot;Список кодов&quot;">​</a></h2><h3 id="_1-information-100-199" tabindex="-1">1. Information [100 - 199] <a class="header-anchor" href="#_1-information-100-199" aria-label="Permalink to &quot;1. Information [100 - 199]&quot;">​</a></h3><ul><li><strong><code>100</code></strong> <em>Continue</em> - Сервер удовлетворён начальными сведениями о запросе, клиент может продолжать пересылать заголовки</li><li>101 Switching Protocols - Сервер выполняет требование клиента и переключает протоколы в соответствии с указанием, данным в поле заголовка Upgrade</li><li><strong><code>102</code></strong> <em>Processing</em> - Запрос принят, но на его обработку понадобится длительное время</li><li><strong><code>103</code></strong> <em>Early Hints</em> - Используется для раннего возврата части заголовков, когда заголовки полного ответа не могут быть быстро сформированы</li></ul><h3 id="_2-success-200-299" tabindex="-1">2. Success [200 - 299] <a class="header-anchor" href="#_2-success-200-299" aria-label="Permalink to &quot;2. Success [200 - 299]&quot;">​</a></h3><ul><li><strong><code>200</code></strong> <em>Ok</em> - Успешный запрос</li><li><strong><code>201</code></strong> <em>Created</em> - Создание нового ресурса</li><li><strong><code>202</code></strong> <em>Accepted</em> - Запрос был принят на обработку, но она не завершена</li><li><strong><code>204</code></strong> <em>No Content</em> - Сервер успешно обработал запрос, но в ответе были переданы только заголовки без тела сообщения</li><li><strong><code>206</code></strong> <em>Partial Content</em> - Сервер удачно выполнил частичный GET-запрос, возвратив только часть сообщения</li></ul><h3 id="_3-redirect-300-399" tabindex="-1">3. Redirect [300 - 399] <a class="header-anchor" href="#_3-redirect-300-399" aria-label="Permalink to &quot;3. Redirect [300 - 399]&quot;">​</a></h3><ul><li><strong><code>300</code></strong> <em>Multiply Choices</em> - По указанному URI существует несколько вариантов предоставления ресурса по типу MIME, по языку или по другим характеристикам</li><li><strong><code>301</code></strong> <em>Moved Permanantly</em> - Запрошенный документ был окончательно перенесен на новый URI, указанный в поле Location заголовка</li><li><strong><code>304</code></strong> <em>Not Modified</em> - Клиент запросил документ методом GET, использовал заголовок If-Modified-Since или If-None-Match и документ не изменился с указанного момента</li><li><strong><code>305</code></strong> <em>Use Proxy</em> - Запрос к запрашиваемому ресурсу должен осуществляться через прокси-сервер</li><li><strong><code>307</code></strong> <em>Temporary Redirect</em> - Запрашиваемый ресурс на короткое время доступен по другому URI, указанный в поле Location заголовка</li><li><strong><code>308</code></strong> <em>Permanant Redirect</em> - Запрашиваемый ресурс был окончательно перенесен на новый URI, указанный в поле Location заголовка</li></ul><h3 id="_4-client-error-400-499" tabindex="-1">4. Client Error [400 - 499] <a class="header-anchor" href="#_4-client-error-400-499" aria-label="Permalink to &quot;4. Client Error [400 - 499]&quot;">​</a></h3><ul><li><strong><code>400</code></strong> <em>Bad Request</em> - Сервер обнаружил в запросе клиента синтаксическую ошибку</li><li><strong><code>401</code></strong> <em>Unauthorized</em> - Для доступа к запрашиваемому ресурсу требуется аутентификация. В заголовке ответ должен содержать поле WWW-Authenticate с перечнем условий аутентификации</li><li><strong><code>403</code></strong> <em>Forbidden</em> - Клиент не уполномочен совершать операции с запрошенным ресурсом</li><li><strong><code>404</code></strong> <em>Not Found</em> - Сервер понял запрос, но не нашёл соответствующего ресурса по указанному URL</li><li><strong><code>405</code></strong> <em>Method Not Allowed</em> - Указанный клиентом метод нельзя применить к текущему ресурсу</li><li><strong><code>406</code></strong> <em>Not Acceptable</em> - Запрошенный URI не может удовлетворить переданным в заголовке характеристикам</li><li><strong><code>407</code></strong> <em>Proxy Authentication Required</em> - Для доступа к запрашиваемому ресурсу требуется аутентификация для прокси-сервера</li><li><strong><code>408</code></strong> <em>Request Timeout</em> - Истекло время ожидания сервером передачи от клиента</li><li><strong><code>409</code></strong> <em>Conflict</em> - Запрос не может быть выполнен из-за конфликтного обращения к ресурсу. Такое возможно, например, когда два клиента пытаются изменить ресурс с помощью метода PUT</li><li><strong><code>410</code></strong> <em>Gone</em> - Ресурс раньше был по указанному URL, но был удалён и теперь недоступен</li><li><strong><code>411</code></strong> <em>Length Required</em> - Для указанного ресурса клиент должен указать Content-Length в заголовке запроса</li><li><strong><code>413</code></strong> <em>Payload To Large</em> - Слишком большой размер тела запроса</li><li><strong><code>414</code></strong> <em>URI Too Long</em> - Слишком длинный URI</li></ul><h3 id="_5-server-error-500-599" tabindex="-1">5. Server Error [500 - 599] <a class="header-anchor" href="#_5-server-error-500-599" aria-label="Permalink to &quot;5. Server Error [500 - 599]&quot;">​</a></h3><ul><li><strong><code>500</code></strong> <em>Internal Server Error</em> - Любая внутренняя ошибка сервера, которая не входит в рамки остальных ошибок класса</li><li><strong><code>501</code></strong> <em>Not Implemented</em> - Сервер не поддерживает возможностей, необходимых для обработки запроса. Типичный ответ для случаев, когда сервер не понимает указанный в запросе метод</li><li><strong><code>502</code></strong> <em>Bad Gateway</em> - Сервер, выступая в роли шлюза или прокси-сервера, получил недействительное ответное сообщение от вышестоящего сервера</li><li><strong><code>503</code></strong> <em>Service Unavailable</em> - Сервер временно не имеет возможности обрабатывать запросы по техническим причинам (обслуживание, перегрузка и прочее)</li><li><strong><code>504</code></strong> <em>Gateway Timeout</em> - Сервер в роли шлюза или прокси-сервера не дождался ответа от вышестоящего сервера для завершения текущего запроса</li><li><strong><code>522</code></strong> <em>Connection Timed Out</em> - CDN не удалось подключиться к веб-серверу</li></ul>',15)])])}const h=o(n,[["render",s]]);export{u as __pageData,h as default};
